"""Compact shop Chromium regression against actual registered project resources.
Set SHOP_QA_OUTPUT_ROOT to an isolated evidence directory containing the verified
published-media-fixture.json and (for before) published-before-resource-cache.json.
Generated harnesses are test caches only. Run the printed .mjs with Node24+.
Native APIs are explicit fixtures; no Minecraft or live redemption is claimed.
"""
from pathlib import Path
import json,sys,os
R=Path(__file__).resolve().parents[2];O=Path(os.environ['SHOP_QA_OUTPUT_ROOT']).resolve()
label=sys.argv[1];mode='before' if label.startswith('before') else 'after';output=O/('browser-'+label);assert not output.exists();output.mkdir()
source=(R/'tests/minigames-browser/run-browser-qa.mjs').read_text(encoding='utf-8').replace('\r\n','\n');boundary=source.index('\ntry{\n  let port;');prefix=source[:boundary]
prefix=prefix.replace("const repo=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..');",'const repo='+json.dumps(str(R))+';').replace("const output=path.join(repo,'build/minigames-browser',new Date().toISOString().replace(/[:.]/g,'-'));",'const output='+json.dumps(str(output))+';')
media=json.loads((O/'published-media-fixture.json').read_text(encoding='utf-8'));coverData=[dict(sku=c['sku'],descriptor=c['descriptor'],src='data:image/gif;base64,'+c['base64']) for c in media['covers']]
setup=r'''(()=>{const f=__fx;f.hold=false;f.state.platform={available:false};f.state.games.find(g=>g.id==='zombie-challenge').ui.currencies=[{id:'challenge_score',label:'战斗结算分',value:'27',scope:'本局',note:'按战斗规则结算；不等同平台积分'},{id:'challenge_coins',label:'兑换币',value:'153',scope:'枪战累计',note:'仅用于枪战兑换和携枪费用'}];const z=f.state.games.find(g=>g.id==='zombie-challenge');z.ui.shop={title:'枪战商店与兑换',sections:[{title:'货币规则',text:'战斗结算分按 10 : 1 换兑换币，余数保留；战术点和平台累计积分各自独立。没有平台积分兑换商品。'},{title:'兑换商店',text:'使用枪战兑换币，背包需要足够空间。',cards:['医疗包','弹药补给','护甲补给','急救包','手榴弹','装备补给'].map((title,i)=>({title,text:(3+i)+' 兑换币',actions:[{label:'兑换',action:'buy',value:'item:'+i+':7:'+(3+i),enabled:true,confirm:'确认兑换 '+title+'？'}]}))},{title:'局内武器购买',text:'战术点显示在游戏内 HUD；局内装备请使用原生武器轮盘购买，按键可在游戏控制设置中独立修改。'},{title:'携带武器',text:'成功开局扣除携枪费：3 兑换币。主武器 1/2 和手枪槽保留原校验。',actions:[{label:'主武器 1 使用免费 MP5',action:'primary',value:'-1',enabled:true},{label:'主武器 2 留空',action:'primary2',value:'-1',enabled:true},{label:'手枪使用免费格洛克',action:'secondary',value:'-1',enabled:true}],cards:[]},{title:'挑战目标与奖励',text:'目标奖励发放兑换币，物品奖励在场外领取。',cards:[{title:'挑战目标',text:'挑战目标',actions:[{label:'领取兑换币',action:'task',value:'0',enabled:true}]}]}]};const horse=f.state.games.find(g=>g.id==='horse_racing');horse.ui.shop={title:'赛马竞技场',sections:[{title:'外观与交易规则',text:'已有模型与商品价格保留；实际兑换以服务器确认结果为准。'},{title:'赛马娘兑换',text:'已发布封面，原生 PNG 回退保留。',cards:COVERS.map((c,i)=>({title:c.descriptor.label.split(' · ')[0],text:'强敌档位与固定词条保留 · 兑换 '+(250+i*100)+' 分',preview:{kind:'preview',id:c.descriptor.resourceId,label:c.descriptor.label,width:156,height:210,sha256:c.descriptor.sha256},previewFallback:{kind:'resource',id:'muxi_horse_racing:textures/gui/umamusume_preview/'+c.sku+'.png',label:'本地外观预览'},actions:[{label:'查看兑换确认',action:'tradeQuoteBuy',value:c.sku,enabled:true,confirm:'查看此商品的服务器兑换确认？'}]}))}]};f.state.games.find(g=>g.id==='tower_defense').ui.shop.sections=[];const original=window.muxiTerminalQuery;window.muxiTerminalQuery=o=>{if(o.request.startsWith('games.context')&&!o.request.includes(':')){o.onSuccess(JSON.stringify({game:'',page:'shop',drafts:{'minigames:shop-game':'zombie-challenge'}}));return;}if(o.request.startsWith('icons.get:')){f.calls.push(o.request);const d=JSON.parse(o.request.slice(10));if(d.kind==='preview'&&f.failGifs){o.onFailure(404,'Explicit missing-resource fixture');return;}const c=COVERS.find(c=>c.descriptor.resourceId===d.id);o.onSuccess(JSON.stringify({revision:1,kind:d.kind,id:d.id,src:c?c.src:FALLBACK}));return;}return original(o);};})();'''.replace('COVERS',json.dumps(coverData,ensure_ascii=False)).replace('FALLBACK',json.dumps('data:image/png;base64,'+media['fallbackPng']))
scenario=r'''
try{
 let port;for(let i=0;i<200;i++){if(fs.existsSync(path.join(profile,'DevToolsActivePort'))){port=Number(fs.readFileSync(path.join(profile,'DevToolsActivePort'),'utf8').split('\n')[0]);break;}if(child.exitCode!==null)throw Error(stderr);await pause(100);}if(!port)throw Error('Chrome startup timeout: '+stderr);
 const targets=await(await fetch('http://127.0.0.1:'+port+'/json')).json();socket=new WebSocket(targets.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise((resolve,reject)=>{socket.addEventListener('open',resolve,{once:true});socket.addEventListener('error',reject,{once:true});});socket.addEventListener('message',event=>{const message=JSON.parse(event.data);if(message.id&&pending.has(message.id)){const cb=pending.get(message.id);pending.delete(message.id);clearTimeout(cb.timer);message.error?cb.reject(Error(JSON.stringify(message.error))):cb.resolve(message.result);}else if(message.method==='Runtime.exceptionThrown')errors.push(message.params.exceptionDetails);});
 await cdp('Page.enable');await cdp('Runtime.enable');await cdp('Page.addScriptToEvaluateOnNewDocument',{source:fixture+'\n'+SETUP});await cdp('Emulation.setDeviceMetricsOverride',{width:1317,height:854,deviceScaleFactor:1,mobile:false});await cdp('Page.navigate',{url:'http://127.0.0.1:'+server.address().port+'/index.html#/games'});await eventually('!!document.querySelector("#mg-shop-game")&&document.querySelector("#mg-content [data-mg-action]")');
 const click=s=>js('{const e=document.querySelector('+JSON.stringify(s)+');e.click();}');const refresh=async()=>{await click('#mg-refresh');await pause(120);};const choose=async value=>{await js('{const e=document.getElementById("mg-shop-game");e.value='+JSON.stringify(value)+';e.dispatchEvent(new Event("change",{bubbles:true}));}');await pause(120);};
 const geometry=[];for(const [width,height] of [[1317,854],[1920,1080],[640,480],[480,320],[320,320]]){await cdp('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:false});await pause(150);await js('document.getElementById("mg-content").scrollTop=0');await shot('zombie-'+MODE+'-'+width+'x'+height);geometry.push(await js(`(()=>{const p=document.getElementById('games'),b=document.querySelector('#mg-content [data-mg-action]').getBoundingClientRect(),c=document.querySelector('#mg-content .guide-card').getBoundingClientRect();return {width:innerWidth,height:innerHeight,actionFullyVisible:b.bottom<=innerHeight&&b.top>=0,productTop:c.top,pageHorizontalOverflow:p.scrollWidth>p.clientWidth};})()`));if(MODE==='after'){await check('first product and action visible '+width+'x'+height,`(()=>{const p=document.getElementById('games'),b=document.querySelector('#mg-content [data-mg-action]').getBoundingClientRect();return p.scrollWidth<=p.clientWidth&&b.top>=0&&b.bottom<=innerHeight;})()`);}}
 if(MODE==='before'){await choose('horse_racing');await eventually('[...document.querySelectorAll(\".mg-preview-primary img\")].filter(i=>!i.hidden&&i.naturalWidth===156).length===6');for(const [width,height] of [[1317,854],[1920,1080],[640,480]]){await cdp('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:false});await pause(150);await shot('horse-before-'+width+'x'+height);}}
 if(MODE==='after'){
  await cdp('Emulation.setDeviceMetricsOverride',{width:1317,height:854,deviceScaleFactor:1,mobile:false});await check('selector points and coins grouped in page toolbar','document.querySelector(".mg-page-nav #mg-shop-game")&&document.querySelector(".mg-page-nav #mg-platform")&&document.querySelector(".mg-page-nav #mg-exchange-balance")');await check('no standalone currency or battle-score block','document.getElementById("mg-currencies").hidden&&!document.getElementById("mg-currencies").textContent&&document.getElementById("mg-exchange-value").textContent==="153"');await check('currency rules collapsed into small help','document.querySelector(".mg-shop-help:not([open])")&&document.querySelector(".mg-shop-help").textContent.includes("货币规则")');
  await js('__fx.state.platform={available:true,points:"9223372036854775807"};__fx.state.games.find(g=>g.id==="zombie-challenge").ui.currencies[1].value="9223372036854775806"');await refresh();await check('exact integer strings preserved','document.getElementById("mg-platform").textContent.includes("9223372036854775807")&&document.getElementById("mg-exchange-value").textContent==="9223372036854775806"');
  await check('loadout and reward actions retained','[...document.querySelectorAll("#mg-content [data-mg-action]")].some(b=>b.textContent.includes("免费 MP5"))&&[...document.querySelectorAll("#mg-content [data-mg-action]")].some(b=>b.textContent.includes("领取兑换币"))');await click('#mg-content [data-mg-action]');await check('redemption confirmation opens','!document.getElementById("mg-confirm").hidden');await click('#mg-confirm-cancel');await check('cancel sends no action','__fx.actions.length===0');await click('#mg-content [data-mg-action]');await click('#mg-confirm-ok');await eventually('__fx.actions.length===1');await pause(350);await check('exact redemption payload retained','__fx.actions[0].game==="zombie-challenge"&&__fx.actions[0].action==="buy"&&__fx.actions[0].value==="item:0:7:3"');
  await choose('horse_racing');await eventually('[...document.querySelectorAll(".mg-preview-primary img")].length===6&&[...document.querySelectorAll(".mg-preview-primary img")].every(i=>!i.hidden&&i.naturalWidth===156)');for(const [width,height] of [[1317,854],[1920,1080],[640,480],[480,320],[320,320]]){await cdp('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:false});await pause(150);await shot('horse-after-'+width+'x'+height);await check('first horse image name price and action visible '+width+'x'+height,`(()=>{const c=document.querySelector('.mg-product-card'),i=c.querySelector('.mg-preview-primary img'),b=c.querySelector('[data-mg-action]'),p=c.querySelector('.mg-product-price');return i.getBoundingClientRect().top>=0&&i.getBoundingClientRect().bottom<=innerHeight&&b.getBoundingClientRect().bottom<=innerHeight&&p&&p.textContent.includes('分');})()`);}await cdp('Emulation.setDeviceMetricsOverride',{width:640,height:480,deviceScaleFactor:1,mobile:false});await pause(120);await js('window.__gifNodes=[...document.querySelectorAll(".mg-preview-primary img")];window.__gifUrls=__gifNodes.map(i=>i.src);document.getElementById("mg-content").scrollTop=70');await refresh();await check('gif nodes URLs and scroll survive snapshot update','__gifNodes.every((i,n)=>i===document.querySelectorAll(".mg-preview-primary img")[n]&&i.src===__gifUrls[n])&&document.getElementById("mg-content").scrollTop===70');await choose('zombie-challenge');await choose('horse_racing');await check('per category scroll restored','document.getElementById("mg-content").scrollTop===70');await choose('tower_defense');await check('empty shop preserved','document.querySelector("#mg-content .task-empty")');await choose('horse_racing');await js('__fx.failGifs=true;TerminalIcons.dispose();TerminalIcons.resume();');await refresh();await eventually('[...document.querySelectorAll(".mg-preview-primary img")].every(i=>i.hidden)&&[...document.querySelectorAll(".mg-preview-backup img")].some(i=>!i.hidden)');await shot('horse-png-fallback');await check('png fallback remains visible','document.querySelector(".mg-preview-backup img:not([hidden])").naturalWidth>0');
  await click('[data-mg-page="lobby"]');await check('lobby room list remains available','document.querySelector("#mg-room-list")');
 }
 assert.deepEqual(errors,[]);fs.writeFileSync(path.join(output,'result.json'),JSON.stringify({success:true,mode:MODE,checks,geometry,errors,scope:'Actual Chromium rendering; native game/economic APIs are explicit fixtures; published GIF bytes verified against live1.4.38 manifest; not MC/MCEF acceptance'},null,2));console.log(JSON.stringify({success:true,mode:MODE,checks:checks.length,geometry}));
}catch(error){await shot('failure').catch(()=>{});fs.writeFileSync(path.join(output,'failure.json'),JSON.stringify({error:String(error),checks,errors,stderr},null,2));throw error;}finally{if(socket){await cdp('Browser.close').catch(()=>{});socket.close();}await new Promise(resolve=>server.close(resolve));}
'''.replace('SETUP',json.dumps(setup,ensure_ascii=False)).replace('MODE',json.dumps(mode))
scenario=scenario.replace('TerminalIcons.dispose();TerminalIcons.resume();','TerminalIcons.invalidate(2);')
if mode=='before':
 prefix=prefix.replace("res.end(fs.readFileSync(target));","const baseline=JSON.parse(fs.readFileSync("+json.dumps(str(O/'published-before-resource-cache.json'))+",'utf8'));const key=path.relative(assets,target).split(path.sep).join('/');res.end(baseline[key]?Buffer.from(baseline[key],'base64'):fs.readFileSync(target));")
scenario=scenario.replace("const geometry=[];","await click('[data-mg-page=\"shop\"]');await choose('zombie-challenge');await eventually('document.querySelector(\"#games.mg-shop #mg-content .mg-shop-title\")');const geometry=[];")
(output/'harness.mjs').write_text(prefix+scenario,encoding='utf-8');print(str(output/'harness.mjs'))
